CREATE FUNCTION techerp_api.inbox_actions_valid(p_actions jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public,pg_temp AS $$ DECLARE a jsonb;k text;x jsonb;BEGIN IF NOT techerp_api.notification_whatsapp_actions_valid(p_actions) THEN RETURN false;END IF;FOR a IN SELECT * FROM jsonb_array_elements(p_actions) LOOP IF a->>'table'='inbox_channel_occurrences' AND a->>'type' IN('create_record','update_record','delete_record') THEN RETURN false;END IF;FOREACH k IN ARRAY ARRAY['then','else','default','actions'] LOOP IF a?k AND NOT techerp_api.inbox_actions_valid(a->k) THEN RETURN false;END IF;END LOOP;FOREACH k IN ARRAY ARRAY['cases','branches'] LOOP IF a?k THEN FOR x IN SELECT * FROM jsonb_array_elements(a->k) LOOP IF NOT techerp_api.inbox_actions_valid(x->'actions') THEN RETURN false;END IF;END LOOP;END IF;END LOOP;END LOOP;RETURN true;END $$;
REVOKE ALL ON FUNCTION techerp_api.inbox_actions_valid(jsonb) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION techerp_api.inbox_workflow_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE config jsonb;k text;v jsonb;BEGIN IF NEW.entity<>'inbox_channel_occurrences' THEN RETURN NEW;END IF;IF auth.uid() IS NULL OR NOT public.is_workspace_member(NEW.workspace_id,auth.uid()) OR public.is_read_only_view() THEN RAISE EXCEPTION 'Ator indisponível.' USING ERRCODE='42501';END IF;
 FOREACH config IN ARRAY ARRAY[NEW.trigger->'notification_event',coalesce(NEW.draft_trigger,NEW.trigger)->'notification_event'] LOOP k:=techerp_api.inbox_event_channel(config->>'key');IF k IS NULL OR jsonb_typeof(config) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(config)x WHERE x NOT IN('key','channel','account_ids')) OR (config?'channel' AND config->>'channel' IS DISTINCT FROM k) OR (config?'account_ids' AND jsonb_typeof(config->'account_ids') IS DISTINCT FROM 'array') THEN RAISE EXCEPTION 'Evento ou canal inválido.' USING ERRCODE='42501';END IF;IF config?'account_ids' THEN IF jsonb_array_length(config->'account_ids')>100 OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(config->'account_ids')x)<>jsonb_array_length(config->'account_ids') THEN RAISE EXCEPTION 'Contas inválidas.' USING ERRCODE='42501';END IF;FOR v IN SELECT * FROM jsonb_array_elements(config->'account_ids') LOOP IF jsonb_typeof(v)<>'string' OR v#>>'{}' !~ '^[a-f0-9-]{36}$' THEN RAISE EXCEPTION 'Conta inválida.' USING ERRCODE='42501';END IF;IF NOT public.workflow_inbox_account_visible(NEW.workspace_id,k,(v#>>'{}')::uuid) THEN RAISE EXCEPTION 'Conta indisponível.' USING ERRCODE='42501';END IF;END LOOP;END IF;END LOOP;
 IF NEW.trigger?'time_based' OR (NEW.draft_trigger IS NOT NULL AND NEW.draft_trigger?'time_based') OR NOT techerp_api.inbox_actions_valid(NEW.actions) OR (NEW.draft_actions IS NOT NULL AND NOT techerp_api.inbox_actions_valid(NEW.draft_actions)) THEN RAISE EXCEPTION 'Origem somente leitura exige ações independentes.' USING ERRCODE='42501';END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION techerp_api.inbox_workflow_guard() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER inbox_workflow_guard BEFORE INSERT OR UPDATE OF entity,trigger,draft_trigger,actions,draft_actions ON public.workflows FOR EACH ROW EXECUTE FUNCTION techerp_api.inbox_workflow_guard();
CREATE FUNCTION techerp_api.inbox_activation_capture() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF NEW.entity='inbox_channel_occurrences' AND NEW.enabled AND NEW.status='published' AND (TG_OP='INSERT' OR NOT OLD.enabled OR OLD.status<>'published' OR NEW.entity IS DISTINCT FROM OLD.entity OR NEW.published_version IS DISTINCT FROM OLD.published_version) THEN INSERT INTO public.inbox_workflow_activations(workflow_id,workspace_id,workflow_version,activated_at) VALUES(NEW.id,NEW.workspace_id,NEW.published_version,clock_timestamp()) ON CONFLICT(workflow_id) DO UPDATE SET workspace_id=excluded.workspace_id,workflow_version=excluded.workflow_version,activated_at=excluded.activated_at;END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION techerp_api.inbox_activation_capture() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER inbox_activation_capture AFTER INSERT OR UPDATE OF entity,enabled,status,published_version ON public.workflows FOR EACH ROW EXECUTE FUNCTION techerp_api.inbox_activation_capture();
CREATE FUNCTION techerp_api.inbox_emit(p_occurrence uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE o record;x record;event_id uuid;event_owner uuid;old uuid;s jsonb;h text;BEGIN SELECT * INTO o FROM public.inbox_channel_occurrences WHERE id=p_occurrence;IF NOT FOUND THEN RETURN NULL;END IF;SELECT * INTO x FROM public.inbox_channel_evidence WHERE id=o.envelope_id;IF NOT FOUND OR x.workspace_id<>o.workspace_id OR x.channel<>o.channel OR x.account_id<>o.account_id OR x.conversation_id<>o.conversation_id OR NOT techerp_api.inbox_account_current(o.workspace_id,o.channel,o.account_id) THEN RETURN NULL;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('inbox-event:'||o.workspace_id||':'||o.event_key||':'||o.occurrence_key,0));SELECT r.event_id INTO old FROM public.notification_business_occurrence_receipts r WHERE r.workspace_id=o.workspace_id AND r.event_key=o.event_key AND r.occurrence_key=o.occurrence_key;IF old IS NOT NULL THEN RETURN old;END IF;
 IF NOT EXISTS(SELECT 1 FROM public.workflows w JOIN public.inbox_workflow_activations a ON a.workflow_id=w.id AND a.workflow_version=w.published_version AND a.workspace_id=w.workspace_id WHERE w.workspace_id=o.workspace_id AND w.entity='inbox_channel_occurrences' AND w.enabled AND w.status='published' AND w.trigger#>>'{notification_event,key}'=o.event_key AND o.received_at>=a.activated_at AND o.occurred_at>=a.activated_at AND (coalesce(w.trigger#>'{notification_event,account_ids}','[]')='[]' OR w.trigger#>'{notification_event,account_ids}' ? o.account_id::text)) THEN RETURN NULL;END IF;
 s:=techerp_api.inbox_snapshot(o.id);event_id:=gen_random_uuid();SELECT created_by INTO event_owner FROM public.workspaces WHERE id=o.workspace_id;IF event_owner IS NULL THEN RETURN NULL;END IF;
 h:=techerp_api.notification_business_event_hash(jsonb_populate_record(NULL::public.workflow_events,jsonb_build_object('id',event_id,'workspace_id',o.workspace_id,'owner_id',event_owner,'entity','inbox_channel_occurrences','entity_id',o.id,'event_type','updated','after',s,'notification_event_key',o.event_key)));
 INSERT INTO public.notification_business_event_proofs(event_id,root_event_id,workspace_id,event_key,source_table,source_id,producer_table,producer_id,reference_id,source_revision,occurrence_key,payload_hash,occurred_at) VALUES(event_id,event_id,o.workspace_id,o.event_key,'inbox_channel_occurrences',o.id,'inbox_channel_evidence',x.id,o.conversation_id,encode(sha256(convert_to(s::text,'UTF8')),'hex'),o.occurrence_key,h,o.occurred_at);
 INSERT INTO public.workflow_events(id,workspace_id,owner_id,entity,entity_id,event_type,after,notification_event_key) VALUES(event_id,o.workspace_id,event_owner,'inbox_channel_occurrences',o.id,'updated',s,o.event_key);
 INSERT INTO public.notification_business_occurrence_receipts(workspace_id,event_key,occurrence_key,event_id,source_table,source_id,producer_table,producer_id,reference_id,source_revision) VALUES(o.workspace_id,o.event_key,o.occurrence_key,event_id,'inbox_channel_occurrences',o.id,'inbox_channel_evidence',x.id,o.conversation_id,encode(sha256(convert_to(s::text,'UTF8')),'hex'));RETURN event_id;END $$;
REVOKE ALL ON FUNCTION techerp_api.inbox_emit(uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION techerp_api.inbox_record(p_evidence uuid,p_kind text,p_message uuid DEFAULT NULL,p_inbound uuid DEFAULT NULL,p_previous text DEFAULT NULL,p_status text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE x record;oid uuid;k text;assignee uuid;claim text;BEGIN SELECT * INTO x FROM public.inbox_channel_evidence WHERE id=p_evidence;IF NOT FOUND THEN RETURN NULL;END IF;k:='shared.'||x.channel||'.'||p_kind;IF techerp_api.inbox_event_channel(k) IS NULL THEN RETURN NULL;END IF;IF x.channel='email' THEN SELECT assigned_to INTO assignee FROM public.email_threads WHERE id=x.conversation_id AND workspace_id=x.workspace_id;ELSIF x.channel='chat' THEN SELECT assignee_id INTO assignee FROM public.live_chat_sessions WHERE id=x.conversation_id AND workspace_id=x.workspace_id;ELSE SELECT assigned_to INTO assignee FROM public.linkedin_conversations WHERE id=x.conversation_id AND workspace_id=x.workspace_id;END IF;claim:=CASE WHEN p_kind IN('conversation_created','first_response') THEN x.conversation_id::text ELSE x.id::text END;
 INSERT INTO public.inbox_channel_occurrences(workspace_id,channel,account_id,conversation_id,event_key,message_id,inbound_id,actor_id,assigned_to,previous_status,status,occurred_at,received_at,occurrence_key,envelope_id) VALUES(x.workspace_id,x.channel,x.account_id,x.conversation_id,k,p_message,p_inbound,x.actor_id,assignee,p_previous,p_status,x.occurred_at,x.received_at,claim,x.id) ON CONFLICT(workspace_id,event_key,occurrence_key) DO NOTHING RETURNING id INTO oid;IF oid IS NULL THEN SELECT id INTO oid FROM public.inbox_channel_occurrences WHERE workspace_id=x.workspace_id AND event_key=k AND occurrence_key=claim;END IF;PERFORM techerp_api.inbox_emit(oid);RETURN oid;END $$;
REVOKE ALL ON FUNCTION techerp_api.inbox_record(uuid,text,uuid,uuid,text,text) FROM PUBLIC,anon,authenticated,service_role;
NOTIFY pgrst,'reload schema';
